import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CQxpk36T.js";const g=JSON.parse('{"title":"The in-page editor","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/editeur.md","filePath":"en/guide/editeur.md","lastUpdated":1793574169000}'),i={name:"en/guide/editeur.md"};function d(n,e,s,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="the-in-page-editor" tabindex="-1">The in-page editor <a class="header-anchor" href="#the-in-page-editor" aria-label="Permalink to &quot;The in-page editor&quot;">​</a></h1><p>The <strong>pencil</strong> at the top right (or Settings → Propriété → Éditer) opens the editor. Tap a building: it becomes an editable model, the others stay in place. Everything is adjusted with your finger, without writing code.</p><h2 id="what-you-can-adjust" tabindex="-1">What you can adjust <a class="header-anchor" href="#what-you-can-adjust" aria-label="Permalink to &quot;What you can adjust&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th></th></tr></thead><tbody><tr><td><strong>Position</strong></td><td>&quot;Déplacer au doigt&quot; (move with finger), then drag on the scene (the camera stops rotating while the button is on); or set it to the centimetre, and the orientation to the degree. &quot;Faîtage dans l&#39;autre sens&quot; (flip ridge) turns the roof a quarter turn on the same footprint</td></tr><tr><td><strong>Dimensions</strong></td><td>Length (along the ridge), width, wall height, ridge; skew of each end, in degrees (<a href="/HAven-docs/en/guide/batiments#skewed-gables">skewed gables</a>)</td></tr><tr><td><strong>Roof</strong></td><td>Two slopes, or lean-to (high side on the courtyard or back side); open shelter on posts</td></tr><tr><td><strong>Building</strong></td><td>Name and kind (colours, icon)</td></tr></tbody></table><p><strong>Ajouter un bâtiment</strong> (add a building) places a 6 × 4 m hut on the courtyard point, with a door and a room (Home Assistant Area with the same id as the building). <strong>Retirer</strong> (remove) deletes it, along with what is attached to it (chicken run, solar panels).</p><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><p>Edits form a <strong>draft</strong>, kept in the browser until saved.</p><ul><li>With <code>npm run dev</code>, <strong>Enregistrer</strong> (save) writes <code>proprietes/&lt;name&gt;/retouches.json</code> and reloads the page: doors, windows and valleys are recomputed.</li><li>On a server, the button becomes <strong>Télécharger</strong> (download): drop the file into the property folder, then run <code>npm run deploy</code> again.</li></ul><h2 id="how-edits-are-applied" tabindex="-1">How edits are applied <a class="header-anchor" href="#how-edits-are-applied" aria-label="Permalink to &quot;How edits are applied&quot;">​</a></h2><p><code>retouches.json</code> is applied <strong>on top of</strong> <code>site.json</code> and <code>propriete.ts</code>: an edited section takes the footprint and heights from the file. To go back to the original description, delete its entry (or the file). The format is described in the <a href="/HAven-docs/en/reference/retouches">reference</a>.</p><div class="warning custom-block"><p class="custom-block-title">What doesn&#39;t follow</p><p>Chicken runs, parking spots, yards and paths don&#39;t follow a moved building: update their coordinates by hand in <code>propriete.ts</code>.</p></div><h2 id="pick-a-position" tabindex="-1">Pick a position <a class="header-anchor" href="#pick-a-position" aria-label="Permalink to &quot;Pick a position&quot;">​</a></h2><p>Rooms, doors and windows are described in <code>propriete.ts</code>, with positions along the walls. <strong>Relever une position</strong> (pick a position, in the editor or Settings → Propriété) gives these values: tap a wall and read, for example</p><blockquote><p>Maison · côté cour · at: 2.35 · hauteur 1.20 m</p></blockquote><p>(courtyard side, height), then copy them into the <a href="/HAven-docs/en/guide/facades#doors">door</a> or <a href="/HAven-docs/en/guide/facades#placing-windows-by-hand">window</a> you want. <strong>Copier</strong> copies the text to the clipboard.</p><table tabindex="0"><thead><tr><th>Tapped</th><th>Text picked</th></tr></thead><tbody><tr><td>A long side</td><td><code>Maison · côté cour · at: 2.35 · hauteur 1.20 m</code></td></tr><tr><td>A gable</td><td><code>Maison · pignon +x · at: -1.10 · hauteur 3.40 m</code> (<code>at</code> across)</td></tr><tr><td>A roof</td><td><code>Maison · toit · le long du faîtage -3.00 m</code> (along the ridge, for solar panels)</td></tr><tr><td>The ground</td><td><code>Sol · x: 9.25, z: 6.00</code> (parking spot, tree, corner of a run)</td></tr></tbody></table><p>A building with several sections says which one: <code>Maison, section 1 · …</code>.</p>',17)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
